/**
 * Cheap uuid syntax check. Avoids round-tripping an invalid id to
 * Postgres (which would 22P02 on every PATCH / SELECT).
 */
function isUuid(s: string | null | undefined): boolean {
  if (!s) return false;
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
    s,
  );
}

function mapDbStatus(s: string): "available" | "selecting" | "occupied" {
  if (s === "available") return "available";
  if (s === "occupied" || s === "reserved") return "occupied";
  return "selecting";
}

function mapRequestTypeToDb(
  t: ServiceRequest["type"],
):
  | "CALL_WAITER"
  | "REQUEST_BILL"
  | "REQUEST_CONDIMENT"
  | "COMPLAINT"
  | "OTHER" {
  switch (t) {
    case "call_waiter":
      return "CALL_WAITER";
    case "request_bill":
      return "REQUEST_BILL";
    case "tissue":
    case "bowl":
    case "sauce":
    case "ice":
    case "grill_change":
    case "charcoal_change":
      return "REQUEST_CONDIMENT";
    case "other":
    default:
      return "OTHER";
  }
}

function mapRequestTypeFromDb(s: string): ServiceRequest["type"] {
  switch (s) {
    case "CALL_WAITER":
      return "call_waiter";
    case "REQUEST_BILL":
      return "request_bill";
    case "REQUEST_CONDIMENT":
      return "tissue";
    case "COMPLAINT":
      return "other";
    default:
      return "other";
  }
}

function mapRequestStatusFromDb(s: string): ServiceRequest["status"] {
  switch (s) {
    case "OPEN":
      return "created";
    case "IN_PROGRESS":
      return "processing";
    case "RESOLVED":
      return "completed";
    default:
      return "created";
  }
}

function rowToOrder(row: any): Order {
  const items = (row.order_details ?? []).map((it: any) => ({
    menuItemId: it.branch_menu_item_id,
    name: it.item_name_snapshot,
    unit: "Phần",
    price: Number(it.unit_price_vnd_snapshot ?? 0),
    price_display: `${Number(it.unit_price_vnd_snapshot ?? 0).toLocaleString("vi-VN")}đ`,
    quantity: Number(it.quantity ?? 1),
    note: it.note ?? "",
  }));
  const computedTotal = items.reduce(
    (sum: number, it: any) => sum + it.price * it.quantity,
    0,
  );

  return {
    id: row.order_id,
    sessionId: row.dining_session_id ?? "",
    tableNumber: "",
    items,
    subtotal: computedTotal,
    serviceCharge: 0,
    vat: 0,
    discount: 0,
    total: computedTotal,
    subtotal_vnd: computedTotal,
    serviceCharge_vnd: 0,
    vat_vnd: 0,
    discount_vnd: 0,
    total_vnd: computedTotal,
    status: (['draft', 'confirmed', 'cooking', 'served', 'completed'].includes(row.status) ? row.status : 'confirmed') as any,
    createdAt: new Date(row.created_at),
  };
}

import { ref, computed } from 'vue'
import { supabase } from '@/lib/supabase'
import { useBranch, throwBranchGuard } from '@/composables/useBranch'
import { useAuth } from '@/composables/useAuth'

export interface MembershipTier {
  id: string
  branch_id: string | null
  name_vi: string
  name_en: string | null
  name_ja: string | null
  min_spent: number
  discount_percent: number
  points_multiplier: number
  color: string
  icon_name: string
  sort_order: number
}

export interface LoyaltyRule {
  id: string
  branch_id: string | null
  points_per_vnd: number
  vnd_per_point: number
  min_redeem_points: number
  max_redeem_percent: number
  is_active: boolean
}

export interface MembershipTierPatch {
  name_vi?: string
  name_en?: string | null
  name_ja?: string | null
  min_spent?: number
  discount_percent?: number
  points_multiplier?: number
  color?: string
  icon_name?: string
  sort_order?: number
}

export function useMembership() {
  const tiers = ref<MembershipTier[]>([])
  const rules = ref<LoyaltyRule | null>(null)
  const { activeBranchId } = useBranch()
  const { profile } = useAuth()

  // Fetch all tier configurations
  async function fetchTiers() {
    if (!activeBranchId.value) throw new Error('No active branch selected')
    const { data, error } = await supabase
      .from('membership_tiers')
      .select('*')
      .or(`branch_id.eq.${activeBranchId.value},branch_id.is.null`)
      .order('sort_order', { ascending: true })
    if (error) throw error
    tiers.value = data as any[]
  }

  // Admin: update tier thresholds
  async function updateTier(tierId: string, patch: Partial<MembershipTierPatch>) {
    const { data, error } = await supabase
      .from('membership_tiers')
      .update(patch)
      .eq('id', tierId)
      .select()
      .single()
    if (error) throw error
    const i = tiers.value.findIndex(t => t.id === tierId)
    if (i >= 0) tiers.value[i] = data as any
    return data as any
  }

  // Fetch loyalty rules
  async function fetchRules() {
    if (!activeBranchId.value) throw new Error('No active branch selected')
    const { data, error } = await supabase
      .from('loyalty_rules')
      .select('*')
      .or(`branch_id.eq.${activeBranchId.value},branch_id.is.null`)
      .order('branch_id', { ascending: false, nullsFirst: false })
      .limit(1)
      .maybeSingle()
    if (error) throw error
    rules.value = data as any
  }

  // Admin: update earn/redeem rates
  async function updateRules(patch: Partial<LoyaltyRule>) {
    if (!activeBranchId.value) throw new Error('No active branch selected')
    const { error } = await supabase
      .from('loyalty_rules')
      .update({ ...patch, updated_at: new Date().toISOString() })
      .or(`branch_id.eq.${activeBranchId.value}`)
    if (error) throw error
    if (rules.value) Object.assign(rules.value, patch)
  }

  // Calculate earn preview (client-side, for checkout UI)
  function previewEarnPoints(orderAmount: number, tierMultiplier = 1.0): number {
    if (!rules.value) return 0
    return Math.floor(orderAmount * rules.value.points_per_vnd * tierMultiplier)
  }

  // Calculate redeem discount (client-side)
  function previewRedeemValue(points: number): number {
    if (!rules.value) return 0
    return points * rules.value.vnd_per_point
  }

  // Earn points after checkout
  async function earnPoints(customerId: string, orderId: string, orderAmount: number) {
    if (!activeBranchId.value) throw new Error('No active branch selected')
    const { data, error } = await supabase.rpc('earn_points_for_order', {
      p_customer_id: customerId,
      p_branch_id: activeBranchId.value,
      p_order_id: orderId,
      p_order_amount: orderAmount
    })
    if (error) throw error
    return data as any
  }

  // Redeem points during checkout
  async function redeemPoints(customerId: string, points: number, orderId?: string) {
    if (!activeBranchId.value) throw new Error('No active branch selected')
    const { data, error } = await supabase.rpc('redeem_points', {
      p_customer_id: customerId,
      p_branch_id: activeBranchId.value,
      p_points: points,
      p_order_id: orderId ?? null
    })
    if (error) {
      if (error.message.includes('P0022')) throw new Error('INSUFFICIENT_POINTS')
      if (error.message.includes('P0021')) throw new Error('BELOW_MIN_REDEEM')
      throw error
    }
    return data as any
  }

  // Admin: manual points adjustment
  async function adjustPoints(customerId: string, type: 'ADJUST_ADD' | 'ADJUST_SUB', points: number, reason: string) {
    if (!activeBranchId.value) throw new Error('No active branch selected')
    const { data, error } = await supabase.rpc('adjust_points', {
      p_customer_id: customerId,
      p_branch_id: activeBranchId.value,
      p_type: type,
      p_points: points,
      p_reason: reason,
      p_admin_id: profile.value?.id
    })
    if (error) throw error
    return data as any
  }

  // Computed
  const tierById = computed(() =>
    Object.fromEntries(tiers.value.map(t => [t.id, t]))
  )

  return {
    tiers,
    rules,
    tierById,
    fetchTiers,
    updateTier,
    fetchRules,
    updateRules,
    previewEarnPoints,
    previewRedeemValue,
    earnPoints,
    redeemPoints,
    adjustPoints
  }
}

import { createClient } from '@supabase/supabase-js'
import type { Database } from '@/types/database'

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL
const supabaseAnonKey =
  import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY ??
  import.meta.env.VITE_SUPABASE_ANON_KEY

const isConfigured = Boolean(supabaseUrl && supabaseAnonKey && supabaseUrl.startsWith('http'))

if (!isConfigured) {
  console.warn(
    '[supabase] VITE_SUPABASE_URL / VITE_SUPABASE_PUBLISHABLE_KEY chưa cấu hình hoặc sai định dạng. ' +
      'App sẽ chạy ở chế độ offline (mock data). Tạo .env.local để kết nối Supabase thật.',
  )
}

/**
 * Khi chưa cấu hình Supabase, tạo một client placeholder với URL/key giả.
 * Mọi gọi API sẽ fail gracefully (trả error) thay vì crash toàn bộ app.
 * Điều này cho phép UI tĩnh hoạt động để test frontend mà không cần backend.
 */
export const supabase = createClient<any>(
  supabaseUrl || 'https://placeholder.supabase.co',
  supabaseAnonKey || 'placeholder-anon-key',
  {
    auth: {
      persistSession: true,
      autoRefreshToken: true,
      detectSessionInUrl: true,
    },
    realtime: {
      params: { eventsPerSecond: 10 },
    },
  },
)

export const isSupabaseConfigured = isConfigured

/**
 * Validate UUID format
 * Format: xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx
 */
export function isValidUUID(value: string | null | undefined): boolean {
  if (!value) return false;
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  return uuidRegex.test(value);
}

